using Telo.Sim.Content;
using Telo.Sim.Core;
using Telo.Sim.Town;
using Telo.Sim.World;

namespace Telo.Sim.Net;

/// <summary>
/// CARRY: what subscribers do with the line. Every evening they ring the Board; it has a fixed number of lines in.
/// More callers than lines means the engaged tone, which costs patience. This is the first bottleneck, and the
/// pattern for every later one (trunks, modem banks, backhaul): use is generated by people, capacity is built by hand.
/// Pure and seeded: the same day with the same lines always plays out the same way, so the lamps can show it live.
/// </summary>
public static class BoardRules
{
    /// <summary>The evening is ten half-hours, 18:00 to 23:00.</summary>
    public const int Slots = 10, FirstHour = 18;
    public const int StartLines = 2, HomeMadeMaxLines = 4, HuntGroupMaxLines = 12;
    public const long CardPrice = 60, LineRentalPerMonth = 6;
    public const int FitMinutes = 20, GaveUpPenalty = 2;
    public const Tools FitNeeds = Tools.LineCard;
    public const string HuntGroupEntry = "alm-hunt";

    /// <summary>How each kind of household uses the Board: chance of ringing in tonight (permille), shortest and longest call (half-hours), favourite time.</summary>
    private static readonly Dictionary<string, (int Calls, int Min, int Max, int Slot)> Habits = new()
    {
        ["curious"] = (700, 1, 2, 3), ["student"] = (800, 2, 3, 6), ["family"] = (600, 1, 2, 2), ["gamer"] = (950, 3, 5, 4),
        ["small-business"] = (500, 1, 1, 0), ["price-sensitive"] = (400, 1, 1, 3), ["reliability-sensitive"] = (600, 1, 2, 2),
        ["tech-inexperienced"] = (300, 1, 1, 1), ["lastmile"] = (500, 1, 1, 2),
    };
    private static readonly (int, int, int, int) Typical = (600, 1, 2, 3);

    public static Exchange Home(GameState s) => s.Exchanges[0];

    /// <summary>A home-made board answers four lines at most. Rolling calls across more needs the hunt group, from the Almanac.</summary>
    public static int MaxLines(GameState s) =>
        s.Entries.GetValueOrDefault(HuntGroupEntry) is EntryStatus.Recalled or EntryStatus.Drifting ? HuntGroupMaxLines : HomeMadeMaxLines;

    /// <summary>Play out one evening at one exchange. Does not change anything.</summary>
    /// <param name="c">Content, so that products which change calling habits (a fast modem, a second line) count. Optional.</param>
    /// <param name="onLine">If given, filled with who is on the Board in each half-hour (for the switchboard's lamps).</param>
    public static EveningReport Evening(GameState s, int day, Exchange ex, ContentDb? c = null, List<string>[]? onLine = null)
    {
        var rng = new DetRng(DetRng.Derive(s.Seed, $"evening:{ex.Id}:{day}"));
        var report = new EveningReport { Day = day, LinesIn = ex.LinesIn, InUse = new int[Slots] };
        var arriving = new List<(string Id, int Len, bool Redial)>[Slots];
        for (int t = 0; t < Slots; t++) arriving[t] = new();
        int appeal = BoardService.Appeal(s);   // a good shelf brings people in more often
        foreach (var cust in s.Customers.Where(x => x.Live && x.Installed && x.HasAccount && x.ExchangeId == ex.Id).OrderBy(x => x.Id, StringComparer.Ordinal))
        {
            var (calls, min, max, slot) = Habits.GetValueOrDefault(cust.Archetype, Typical);
            calls = Math.Min(1000, calls * (100 + appeal) / 100);
            if (!rng.ChancePermille(calls)) continue;
            int start = Math.Clamp(slot + rng.Range(-2, 3), 0, Slots - 1);
            int len = rng.Range(min, max + 1);
            if (c is not null)
                foreach (var pid in cust.Products)
                    if (c.Products.TryGetValue(pid, out var prod)) len = Math.Max(1, (len * prod.CallLengthPermille + 500) / 1000);
            arriving[start].Add((cust.Id, len, false));
        }
        var ends = new List<(int End, string Id)>();
        for (int t = 0; t < Slots; t++)
        {
            ends.RemoveAll(e => e.End <= t);
            foreach (var (id, len, redial) in arriving[t])
            {
                report.Attempts++;
                if (ends.Count < ex.LinesIn) { ends.Add((t + len, id)); continue; }
                report.Engaged++;
                if (!redial && t + 1 < Slots) arriving[t + 1].Add((id, len, true));   // one more try in half an hour
                else report.GaveUp.Add(id);
            }
            report.InUse[t] = ends.Count;
            if (onLine is not null && t < onLine.Length) onLine[t] = ends.Select(e => e.Id).ToList();
            if (ends.Count > report.Peak) { report.Peak = ends.Count; report.BusiestSlot = t; }
        }
        return report;
    }

    /// <summary>Yesterday evening happened: the people who never got through remember it.</summary>
    public static void ApplyEvening(GameState s, ContentDb c, int day)
    {
        var report = Evening(s, day, Home(s), c);
        s.LastEvening = report;
        if (!Onboarding.Reached(s, c, OnboardingStep.Free)) { report.Engaged = 0; report.GaveUp.Clear(); return; } // not while they are learning the round
        s.EngagedThisMonth += report.Engaged;
        foreach (var id in report.GaveUp)
            if (s.Customers.FirstOrDefault(x => x.Id == id) is { } cust) cust.Satisfaction = Math.Max(0, cust.Satisfaction - GaveUpPenalty);
    }

    public static bool CanAddLine(GameState s) => Home(s).LinesIn + s.LineCards < MaxLines(s);

    public static bool BuyCard(GameState s)
    {
        if (s.Cash < CardPrice || !CanAddLine(s)) return false;
        s.Cash -= CardPrice; s.LineCards++;
        s.Emit(EventKind.Money, $"Bought a line card for ${CardPrice}. It needs fitting beside the frame, and the line is ${LineRentalPerMonth} a month.");
        return true;
    }

    /// <summary>Slot a bought card in: one more line into the Board from tonight.</summary>
    public static bool FitCard(GameState s, Tools onSite)
    {
        if (s.LineCards <= 0 || (onSite & FitNeeds) != FitNeeds || Home(s).LinesIn >= MaxLines(s)) return false;
        s.LineCards--; Home(s).LinesIn++;
        return true;
    }

    public static long MonthlyRental(GameState s) => s.Exchanges.Sum(e => e.LinesIn) * LineRentalPerMonth;

    /// <summary>"19:30" for a half-hour slot.</summary>
    public static string Clock(int slot) => $"{FirstHour + slot / 2}:{(slot % 2 == 0 ? "00" : "30")}";
}
